-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

CREATE OR REPLACE FUNCTION public.search_profile_ids(p_query text)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
  with terms as (
    select distinct t
    from regexp_split_to_table(
      lower(regexp_replace(coalesce(p_query, ''), '@', ' ', 'g')), '\s+'
    ) as t
    where length(t) >= 1
  ),
  profile_text as (
    select
      p.id,
      coalesce(p.display_name, p.username, '') as name,
      p.username,
      concat_ws(' ', p.username, p.display_name, p.headline) as blob
    from public.profiles p
    where p.suspended_at is null
      and (p.username is not null or p.display_name is not null)
  ),
  scored as (
    select
      pt.id,
      bool_or(lower(coalesce(pt.username, '')) = t.t) as exact_username,
      count(*) filter (
        where pt.blob ilike '%' || t.t || '%'
           or word_similarity(t.t, pt.name) >= 0.45
      ) as hits,
      bool_or(pt.name ilike '%' || t.t || '%') as name_hit,
      max(similarity(pt.name, lower(coalesce(p_query, '')))) as sim
    from profile_text pt
    cross join terms t
    group by pt.id
  )
  select id from scored
  where hits > 0
  order by exact_username desc, hits desc, name_hit desc, sim desc
$function$;

grant execute on function public.search_profile_ids(p_query text) to anon;
grant execute on function public.search_profile_ids(p_query text) to authenticated;
grant execute on function public.search_profile_ids(p_query text) to public;
grant execute on function public.search_profile_ids(p_query text) to service_role;
